            if u not in bot_users:
                real_count += 1
    results.append((real_count, msg))

# Sort by reaction count descending
results.sort(key=lambda x: x[0], reverse=True)

print("=== Reaction Leaderboard (real people only) ===")
for rank, (count, msg) in enumerate(results[:3], 1):
